function downloadSection(lang){const bg=lang==='bg';return `<div class="download-intro"><img src="assets/tasktime.svg" alt="TaskTime" width="72" height="72"><p>${bg?'Избери браузъра, в който работиш. Свали тестовия ZIP пакет и следвай стъпките за ръчно инсталиране. Двата пакета имат една и съща логика.':'Choose the browser you use for work. Download the beta ZIP and follow the manual installation steps. Both packages use the same logic.'}</p></div><div class="cards browser-cards">${['Chrome','Opera'].map(browser=>`<article class="card"><div class="browser-title"><img src="assets/${browser.toLowerCase()}.svg" alt="" width="44" height="44"><div><h3>${browser==='Chrome'?'Google Chrome':'Opera Browser'}</h3><small>DESKTOP · BETA 0.1.1 · ZIP</small></div></div><p>${bg?'Личен отчет, статистика по тип, смени и постоянен панел.':'Personal report, statistics by type, shifts and a persistent question panel.'}</p><a class="download-button" download href="downloads/tasktime-${browser.toLowerCase()}-0.1.1.zip"><span aria-hidden="true">↓</span> ${bg?'Свали за':'Download for'} ${browser}<span class="file-size">~24 KB</span></a><a class="install-link" href="#installation">${bg?'Как се инсталира?':'How do I install it?'} →</a></article>`).join('')}</div><div class="callout beta-notice"><strong>${bg?'Първа тестова версия, не официално издание.':'First beta, not a store release.'}</strong> ${bg?'Пакетите са реални и могат да се заредят ръчно. Автоматичното разпознаване още не е проверено в реалните служебни сайтове или в инсталирани Chrome/Opera. Първо сравни пробни записи.':'These are real packages for manual loading. Automatic detection has not yet been verified on the live work sites or in installed Chrome/Opera. Compare trial records first.'}</div><div class="release-grid"><div><h3>${bg?'Включено в 0.1.1':'Included in 0.1.1'}</h3><ul><li>${bg?'Иконка по статус: червена извън смяна, оранжева при потвърдена почивка, зелена при работа.':'Status icon: red off shift, orange on a confirmed break, green while working.'}</li><li>${bg?'Разпознаване по тип + ID; Finish сам по себе си не приключва задача.':'Type + ID recognition; a Finish click alone does not complete a task.'}</li><li>${bg?'9 типа: брой, най-бърза, най-бавна, средно и общо време.':'9 types: count, fastest, slowest, average and total time.'}</li><li>${bg?'Разпознаване на видимите Clock In / Clock Out бутони в Ximble.':'Detection of visible Clock In / Clock Out buttons in Ximble.'}</li><li>${bg?'План за смяна, почивки, въпроси за overtime и панел без отнемане на фокус.':'Shift plan, breaks, overtime questions and a panel that does not steal focus.'}</li><li>${bg?'Локална история, преглед на неясни задачи, CSV и JSON архив.':'Local history, uncertain-task review, CSV and JSON backup.'}</li></ul></div><div><h3>${bg?'Ограничения на теста':'Beta limitations'}</h3><ul><li>${bg?'Finish & Exit и пропуски над 45 секунди остават за преглед.':'Finish & Exit and observation gaps over 45 seconds require review.'}</li><li>${bg?'Началото на вече започнала смяна не се възстановява назад.':'Earlier time in an already-started shift is not reconstructed.'}</li><li>${bg?'Дръж Ximble отворен; няма синхронизация между браузъри и профили.':'Keep Ximble open; no synchronization across browsers or profiles.'}</li><li>${bg?'XLSX, възстановяване от JSON, норми и пълен разчет на чакане предстоят.':'XLSX, JSON restore, time targets and full waiting-time accounting are planned.'}</li></ul></div></div><div id="installation" class="installation"><span class="eyebrow">${bg?'ИНСТАЛИРАНЕ · 5 СТЪПКИ':'INSTALLATION · 5 STEPS'}</span><h3>${bg?'От ZIP до иконка в браузъра':'From ZIP to a browser icon'}</h3><ol><li>${bg?'Свали пакета за своя браузър и го разархивирай в постоянна папка.':'Download your browser’s package and extract it into a permanent folder.'}</li><li>${bg?'Отвори страницата за разширения. Копирай съответния адрес в адресната лента:':'Open the extensions page. Copy the appropriate address into the address bar:'}<div class="browser-addresses"><code>chrome://extensions</code><code>opera://extensions</code></div></li><li>${bg?'Включи Developer mode / Режим за програмисти и избери Load unpacked / Зареждане на разопаковано разширение.':'Enable Developer mode and choose Load unpacked.'}</li><li>${bg?'Избери разархивираната папка, в която се намира manifest.json — не самия ZIP.':'Select the extracted folder containing manifest.json — not the ZIP itself.'}</li><li>${bg?'Закачи иконката TaskTime. Презареди Redstone и Ximble в същия профил. Клик върху иконката отваря отчета.':'Pin TaskTime. Reload Redstone and Ximble in the same profile. Click the icon to open your report.'}</li></ol><p class="caption">${bg?'При обновяване замени файловете в същата папка и натисни Reload на съществуващата добавка. Не я премахвай: това изтрива локалните данни. Първо направи JSON архив.':'To update, replace the files in the same folder and Reload the existing extension. Do not remove it: removal deletes local data. Export a JSON backup first.'}</p><p class="caption">${bg?'Официални инструкции:':'Official instructions:'} <a href="https://developer.chrome.com/docs/extensions/get-started/tutorial/hello-world#load-unpacked" target="_blank" rel="noopener">Chrome</a> · <a href="https://help.opera.com/en/extensions/testing/" target="_blank" rel="noopener">Opera</a></p></div><div class="icon-download"><img src="assets/tasktime.svg" width="60" height="60" alt="TaskTime — clock with checkmark"><div><h3>${bg?'Иконката на TaskTime':'The TaskTime icon'}</h3><p>${bg?'Часовник + отметка: време и завършена задача. Включена е в двата пакета в размери 16, 32, 48 и 128 px.':'Clock + checkmark: time and completed work. Included in both packages at 16, 32, 48 and 128 px.'}</p><a href="assets/tasktime.svg" download>${bg?'Свали SVG':'Download SVG'}</a> · <a href="assets/tasktime-128.png" download>PNG 128 px</a></div></div><p class="caption">${bg?'Всички работни данни остават в браузъра. Няма сървър, аналитика или автоматични действия по задачите. Иконите на браузърите обозначават съвместимост; проектът не е свързан с Google или Opera.':'All work data stays in the browser. No server, analytics or automatic task actions. Browser icons identify compatibility; this project is not affiliated with Google or Opera.'} <a href="downloads/checksums.json">SHA-256</a></p>`}
for(const lang of ['bg','en']){const d=data[lang],bg=lang==='bg';d.badge=bg?'BETA 0.1.1 · ПАКЕТИ ЗА РЪЧНО ИНСТАЛИРАНЕ':'BETA 0.1.1 · MANUAL INSTALLATION PACKAGES';d.aside=bg?'Концепция + тестова версия 0.1.1.<br>Сайтът не събира работни данни.':'Concept + beta 0.1.1.<br>This website does not collect work data.';d.items.unshift(bg?'Сваляне и инсталиране':'Download & install');d.sections.unshift([bg?'TaskTime за твоя браузър.':'TaskTime for your browser.',downloadSection(lang)]);const last=d.sections.at(-1);last[1]=last[1].replace('Тази страница е спецификация на идеята — самата добавка още не е създадена.','Налична е тестова версия 0.1.1 от секцията за сваляне. Тя покрива основния поток; останалите описани възможности са план и изискват проверка в реалните сайтове.').replace('This page specifies the concept; the extension itself has not been built.','Beta 0.1.1 is available in the download section. It implements the core flow; the broader capabilities remain a plan and require live-site verification.');}
const baseRender=render;render=function(lang){baseRender(lang);const a=document.createElement('a');a.href='#s0';a.className='hero-download';a.textContent=lang==='en'?'↓ Download beta for your browser':'↓ Свали тестовата добавка';document.querySelector('.hero').append(a)};render(document.documentElement.lang);
